package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DatabindContext;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassNameIdResolver__typeFromId_TriageGen1Test {

    private TypeFactory typeFactory;
    private JavaType baseType;
    private ClassNameIdResolver resolver;
    private DeserializationContext deserializationContext;

    @Before
    public void setUp() {
        typeFactory = mock(TypeFactory.class);
        baseType = mock(JavaType.class);
        deserializationContext = mock(DeserializationContext.class);
        // We need to use a subclass or spy because the method is protected
        resolver = new ClassNameIdResolver(baseType, typeFactory) {
            @Override
            public JavaType typeFromId(DatabindContext context, String id) throws IOException {
                return super._typeFromId(id, context);
            }
        };
    }

    /**
     * Helper to access the protected method via reflection or a subclass wrapper.
     * Since we provided a subclass in setUp, we cast to it.
     */
    private JavaType invokeTypeFromId(String id, DatabindContext ctxt) throws IOException {
        return resolver.typeFromId(ctxt, id);
    }

    @Test
    public void testTypeFromId_WithGenerics() throws IOException {
        String idWithGenerics = "java.util.List<java.lang.String>";
        JavaType expectedType = mock(JavaType.class);

        when(deserializationContext.getTypeFactory()).thenReturn(typeFactory);
        when(typeFactory.constructFromCanonical(idWithGenerics)).thenReturn(expectedType);

        JavaType result = invokeTypeFromId(idWithGenerics, deserializationContext);

        assertEquals(expectedType, result);
    }










}
